        cookies_pyload = requests.utils.dict_from_cookiejar(cookies_pyload_jar)
        
        
        # Fault100. HTTP Status 500.
        headers = {}
        headers["content-type"] = "application/json"
        body = {}
        headers['Accept'] = "application/json"
        res_0 = requests \
                .post(self.baseUrlOfSut + "/api/add_package",
                    headers=headers, cookies=cookies_pyload, data=body, timeout=EM_HTTP_TIMEOUT_S, verify=False)
        
        assert res_0.status_code == 500
        assert "application/json" in res_0.headers["content-type"]
        assert res_0.json()["error"] == "Internal server error"
    
    
